  UpdateWorkspaceStatus(request: UpdateWorkspaceStatusRequest): Promise<UpdateWorkspaceStatusResponse>;
  /** Agent authentication and context retrieval */
  AuthenticateAgent(request: AuthenticateAgentRequest): Promise<AuthenticateAgentResponse>;
  /** Query workspace repository */
