    const data = UpdateWorkspaceStatusRequest.encode(request).finish();
    const promise = this.rpc.request(this.service, "UpdateWorkspaceStatus", data);
    return promise.then((data) => UpdateWorkspaceStatusResponse.decode(new BinaryReader(data)));
